let ws;
let commandId = 0;
const pending = new Map();
const runtimeErrors = [];

async function cdp(method, params = {}) {
  const id = ++commandId;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => { pending.delete(id); reject(new Error(`CDP timeout: ${method}`)); }, 15000);
    pending.set(id, message => { clearTimeout(timer); if (message.error) reject(new Error(message.error.message)); else resolve(message.result); });
  });
}
async function evaluate(expression) {
  const result = await cdp("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true, userGesture: true });
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description || result.exceptionDetails.text || "Browser evaluation failed.");
  return result.result?.value;
}
async function waitFor(predicate, label, timeout = 30000) {
  const end = Date.now() + timeout;
  while (Date.now() < end) {
    if (await predicate().catch(() => false)) return;
    await new Promise(resolve => setTimeout(resolve, 200));
  }
  const state = await evaluate("JSON.stringify({url:location.href,body:document.body.innerText.slice(0,1800),region:{x:document.querySelector('[data-region-map]')?.dataset.playerX,y:document.querySelector('[data-region-map]')?.dataset.playerY,navResult:document.querySelector('[data-region-map]')?.dataset.navResult,movementStop:document.querySelector('[data-region-map]')?.dataset.movementStop}})").catch(error => error.message);
  throw new Error(`Timed out waiting for ${label}. Browser state: ${state}`);
}
async function waitText(text, timeout) { return waitFor(() => evaluate(`document.body.innerText.includes(${JSON.stringify(text)})`), text, timeout); }
async function clickButton(text) {
  const result = JSON.parse(await evaluate(`JSON.stringify((() => { const buttons=[...document.querySelectorAll('button')]; const b=buttons.find(x=>x.innerText.trim().toLowerCase().includes(${JSON.stringify(text.toLowerCase())})); if(!b||b.disabled)return {ok:false,buttons:buttons.map(x=>x.innerText.trim()).filter(Boolean).slice(-30),panel:document.querySelector('[data-healthclues-plan-builder]')?.innerText.slice(0,1800)||''};b.click();return {ok:true}; })())`));
  assert.equal(result.ok, true, `Could not click button containing ${text}. Available state: ${JSON.stringify(result)}`);
}
async function clickJourneyTourButton(text) {
  const result = await evaluate(`(()=>{const button=[...document.querySelectorAll('.hc-inventory-tour-controls button')].find(node=>node.innerText.trim()===${JSON.stringify(text)});if(!button||button.disabled)return false;button.click();return true})()`);
  assert.equal(result,true,`Could not click My Journey tour action ${text}.`);
}
