    const focusState=JSON.parse(await evaluate(`JSON.stringify((()=>{const target=document.querySelector(${JSON.stringify(sectionSelector)}),note=document.querySelector('[data-journey-tour-dialogue]'),box=target?.getBoundingClientRect(),bubble=note?.getBoundingClientRect(),backdrop=document.querySelector('.hc-game-modal-backdrop.is-journey-guided'),map=document.querySelector('[data-region-map]'),companion=document.querySelector('.hc-region-companion'),d=backdrop?.getBoundingClientRect(),m=map?.getBoundingClientRect(),muted=[...document.querySelectorAll('.hc-my-journey-focus.is-tour-muted,.hc-my-journey-section.is-tour-muted')],center=box&&document.elementsFromPoint(box.left+box.width/2,box.top+box.height/2),worldPoint=m&&{x:m.left+Math.min(20,m.width/4),y:m.top+Math.min(20,m.height/4)},worldHit=worldPoint&&document.elementFromPoint(worldPoint.x,worldPoint.y);return {targetClass:target?.className,activeCount:document.querySelectorAll('[data-journey-tour-active="true"]').length,mutedCount:muted.length,mutedOpacity:muted.map(item=>Number.parseFloat(getComputedStyle(item).opacity)),targetFocused:document.activeElement===target,describedBy:target?.getAttribute('aria-describedby')===note?.id,skipPresent:!![...document.querySelectorAll('[data-journey-tour-dialogue] button')].find(button=>button.innerText.includes('Skip Tour')),noteImmediatelyBefore:note?.parentElement===target?.parentElement&&note?.nextElementSibling===target,overlaps:!!box&&!!bubble&&box.top<bubble.bottom&&bubble.top<box.bottom,dimmedBackdrop:!!backdrop,backgroundCompanionHidden:!companion||getComputedStyle(companion).display==='none',worldDimCoversMap:!!d&&!!m&&d.left<=m.left&&d.right>=m.right&&d.top<=m.top&&d.bottom>=m.bottom,worldDimCoversViewport:!!d&&d.left<=0&&d.top<=0&&d.right>=innerWidth&&d.bottom>=innerHeight,activeTargetPaintedAboveWorldDim:!!center?.length&&center.indexOf(target)>=0&&center.indexOf(backdrop)>=0&&center.indexOf(target)<center.indexOf(backdrop),blocksWorldPointer:!!backdrop&&worldHit===backdrop}})())`));
